# The demos establish the interior fill color by square frame side length.
FRAME_COLOR = {5: 8, 7: 4, 9: 3}


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0]) if grid else 0
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))

            top = min(y for y, _ in cells)
            bottom = max(y for y, _ in cells)
            left = min(x for _, x in cells)
            right = max(x for _, x in cells)
            height, width = bottom - top + 1, right - left + 1
            if height != width or height not in FRAME_COLOR or height < 3:
                continue

            frame = set(cells)
            perimeter = (
                {(top, x) for x in range(left, right + 1)}
                | {(bottom, x) for x in range(left, right + 1)}
                | {(y, left) for y in range(top, bottom + 1)}
                | {(y, right) for y in range(top, bottom + 1)}
            )
            if not perimeter.issubset(frame):
                continue

            fill = FRAME_COLOR[height]
            for y in range(top + 1, bottom):
                for x in range(left + 1, right):
                    if grid[y][x] == 0:
                        out[y][x] = fill
    return out


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
